import { useMetadataStore } from '@components/app-wrapper/metadata-provider/metadata-provider'
import { getAnalyticsEndpoint } from '@components/plugin-wrapper/hooks/query-tools-common'
import { getAdaptedVisualization as getAdaptedVisualizationForLL } from '@components/plugin-wrapper/hooks/query-tools-line-list'
import {
    getAdaptedVisualization as getAdaptedVisualizationForPT,
    getCellValueAnalyticsRequestParams,
} from '@components/plugin-wrapper/hooks/query-tools-pivot-table'
import { Analytics } from '@dhis2/analytics'
// eslint-disable-next-line no-restricted-imports
import { useConfig, useDataEngine } from '@dhis2/app-runtime'
import { useAppSelector, useCurrentUser } from '@hooks'
import { transformVisualizationForAnalyticsRequest } from '@modules/analytics-request'
import {
    isCurrentVisualizationNew,
    isCurrentVisualizationPersisted,
    isVisualizationEmpty,
    isVisualizationWithTimeDimension,
} from '@modules/visualization/guards'
import { getSingleProgramFromVisualization } from '@modules/visualization/program'
import { getCurrentVis } from '@store/current-vis-slice'
import { useCallback, useState } from 'react'
import type { DownloadFn, DownloadType, FileFormat } from './types'

const getDownloadTarget = (type: DownloadType, format: FileFormat) => {
    if (type === 'table') {
        return format === 'html+css' ? '_blank' : '_top'
    }
    return ['csv', 'xls', 'xlsx'].includes(format) ? '_top' : '_blank'
}

type UseDownloadResult = {
    isDownloadDisabled: boolean
    download: DownloadFn
}

const useDownload: (relativePeriodDate?: string) => UseDownloadResult = (
    relativePeriodDate
) => {
    const config = useConfig()
    const dataEngine = useDataEngine()
    const [analyticsEngine] = useState(() => Analytics.getAnalytics(dataEngine))

    const currentVis = useAppSelector(getCurrentVis)
    const currentUser = useCurrentUser()
    const metadataStore = useMetadataStore()

    const downloadForLL: DownloadFn = useCallback(
        ({ type, format, idScheme }) => {
            if (isVisualizationEmpty(currentVis)) {
                return
            }

            const visualization =
                transformVisualizationForAnalyticsRequest(currentVis)

            const { adaptedVisualization, headers, parameters } =
                getAdaptedVisualizationForLL(visualization)

            let req = new analyticsEngine.request()
                .withPath(
                    `${getAnalyticsEndpoint(visualization.outputType)}/query`
                )
                .withFormat(format)
                .withDisplayProperty(currentUser.settings.displayProperty)

            if (visualization.showHierarchy) {
                req = req.withHierarchyMeta()
            }

            // TEI can use multiple programs
            if (visualization.outputType !== 'TRACKED_ENTITY_INSTANCE') {
                req = req
                    .withProgram(
                        getSingleProgramFromVisualization(visualization).id
                    )
                    .withOutputType(visualization.outputType)
            } else if (visualization.trackedEntityType?.id) {
                req = req.withTrackedEntityType(
                    visualization.trackedEntityType.id
                )
            }

            if (
                relativePeriodDate &&
                isVisualizationWithTimeDimension(visualization)
            ) {
                req = req.withRelativePeriodDate(relativePeriodDate)
            }

            const sorting = visualization.sorting?.[0]
            if (sorting?.direction === 'ASC') {
                req = req.withAsc(sorting.dimension)
            } else if (sorting?.direction === 'DESC') {
                req = req.withDesc(sorting.dimension)
            }

            switch (type) {
                case 'table':
                    req = req
                        .fromVisualization(adaptedVisualization)
                        .withParameters({
                            ...parameters,
                            headers,
                            dataIdScheme: 'NAME',
                            outputIdScheme: 'NAME',
                            paging: false,
                        })

                    break
                case 'plain':
                    req = req
                        .fromVisualization(adaptedVisualization, true)
                        .withParameters({
                            ...parameters,
                            headers,
                            paging: false,
                        })
                        .withOutputIdScheme(idScheme)

                    // fix option set option names
                    if (idScheme === 'NAME') {
                        req = req.withParameters({ dataIdScheme: idScheme })
                    }

                    break
            }

            const url = new URL(
                `${config.baseUrl}/api/${config.apiVersion}/${req.buildUrl()}`,
                `${globalThis.location.origin}${globalThis.location.pathname}`
            )

            Object.entries(req.buildQuery()).forEach(([key, value]) =>
                // TODO: buildQuery return value should be typed to avoid the need of the String casting
                url.searchParams.append(key, String(value))
            )

            window.open(url, getDownloadTarget(type, format))
        },
        [
            analyticsEngine,
            config.baseUrl,
            config.apiVersion,
            currentVis,
            currentUser.settings,
            relativePeriodDate,
        ]
    )

    const downloadForPT: DownloadFn = useCallback(
        ({ type, format, idScheme }) => {
            if (isVisualizationEmpty(currentVis)) {
                return
            }

            const visualization =
                transformVisualizationForAnalyticsRequest(currentVis)

            const { adaptedVisualization, parameters } =
                getAdaptedVisualizationForPT(visualization)

            let req = new analyticsEngine.request()
                .withPath(
                    `${getAnalyticsEndpoint(visualization.outputType)}/aggregate`
                )
                .withFormat(format)
                .withDisplayProperty(currentUser.settings.displayProperty)
                .withProgram(
                    getSingleProgramFromVisualization(visualization).id
                )

            if (visualization.showHierarchy) {
                req = req.withHierarchyMeta()
            }

            if (visualization.sortOrder) {
                req = req.withSortOrder(
                    visualization.sortOrder === 1 ? 'ASC' : 'DESC'
                )
            }

            if (visualization.topLimit) {
                req = req.withLimit(visualization.topLimit)
            }

            const cellValueParams = getCellValueAnalyticsRequestParams(
                visualization,
                metadataStore
            )
            if (cellValueParams) {
                req = req
                    .withValue(cellValueParams.value)
                    .withAggregationType(cellValueParams.aggregationType)
            }

            if (
                relativePeriodDate &&
                isVisualizationWithTimeDimension(visualization)
            ) {
                req = req.withRelativePeriodDate(relativePeriodDate)
            }

            switch (type) {
                case 'table':
                    req = req
                        .fromVisualization(adaptedVisualization)
                        .withParameters({
                            ...parameters,
                            dataIdScheme: 'NAME',
                            outputIdScheme: 'NAME',
                            paging: false,
                        })

                    break
                case 'plain':
                    req = req
                        .fromVisualization(adaptedVisualization, true)
                        .withParameters({
                            ...parameters,
                            paging: false,
                        })
                        .withOutputIdScheme(idScheme)

                    // fix option set option names
                    if (idScheme === 'NAME') {
                        req = req.withParameters({ dataIdScheme: idScheme })
                    }

                    break
            }

            const url = new URL(
                `${config.baseUrl}/api/${config.apiVersion}/${req.buildUrl()}`,
                `${globalThis.location.origin}${globalThis.location.pathname}`
            )

            Object.entries(req.buildQuery()).forEach(([key, value]) =>
                // TODO: buildQuery return value should be typed to avoid the need of the String casting
                url.searchParams.append(key, String(value))
            )

            window.open(url, getDownloadTarget(type, format))
        },
        [
            analyticsEngine,
            config.baseUrl,
            config.apiVersion,
            currentVis,
            currentUser.settings,
            metadataStore,
            relativePeriodDate,
        ]
    )

    const isDownloadEnabled =
        isCurrentVisualizationNew(currentVis) ||
        isCurrentVisualizationPersisted(currentVis)

    return {
        isDownloadDisabled: !isDownloadEnabled,
        download:
            currentVis.type === 'PIVOT_TABLE' ? downloadForPT : downloadForLL,
    }
}

export { useDownload }
